import{_ as l,r as e,o as c,c as i,e as t,a as s,s as r,d as a}from"./chunks/framework.CXcwiNg-.js";const x=JSON.parse('{"title":"Конфигурация почты - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как настроить сервисы для отправки почты.","frontmatter":{"subtitle":"Узнайте, как настроить сервисы для отправки почты."},"headers":[{"level":2,"title":"Предварительные требования для драйверов","slug":"предварительные-требования-для-драиверов","link":"#предварительные-требования-для-драиверов","children":[{"level":3,"title":"Драйвер Mailgun","slug":"драивер-mailgun","link":"#драивер-mailgun","children":[]},{"level":3,"title":"Драйвер Postmark","slug":"драивер-postmark","link":"#драивер-postmark","children":[]},{"level":3,"title":"Драйвер SES","slug":"драивер-ses","link":"#драивер-ses","children":[]}]},{"level":2,"title":"Почта и локальная разработка","slug":"почта-и-локальная-разработка","link":"#почта-и-локальная-разработка","children":[{"level":3,"title":"Драйвер Log","slug":"драивер-log","link":"#драивер-log","children":[]},{"level":3,"title":"Универсальный получатель","slug":"универсальныи-получатель","link":"#универсальныи-получатель","children":[]},{"level":3,"title":"Режим имитации отправки","slug":"режим-имитации-отправки","link":"#режим-имитации-отправки","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}]}],"relativePath":"3.x/ru/setup/mail-config.md","filePath":"3.x/ru/setup/mail-config.md"}'),g={name:"3.x/ru/setup/mail-config.md"};function u(d,n,k,h,m,f){const o=e("pre-heading"),p=e("post-heading");return c(),i("div",null,[t(o),n[0]||(n[0]=s("h1",null,"Конфигурация почты",-1)),t(p),n[1]||(n[1]=r(`<p>October CMS предоставляет драйверы для SMTP, Mailgun, SparkPost, Amazon SES и <code>sendmail</code>, позволяя быстро начать отправку почты через локальный или облачный сервис по вашему выбору.</p><p>Существует два способа настройки почтовых сервисов: через панель администратора в разделе <strong>Настройки → Настройки почты</strong> или путём обновления значений конфигурации по умолчанию. В приведённых примерах мы будем обновлять значения конфигурации в файлах.</p><div class="custom-block tip"><p>Экран настроек почты в панели администратора переопределяет настройки, заданные в файлах конфигурации. Нажатие кнопки <strong>Сбросить по умолчанию</strong> обновит настройки почты до актуальных значений. Если вы не нажмёте <strong>Сохранить</strong> в этой форме, настройки будут по-прежнему загружаться из файлов конфигурации.</p></div><h2 id="предварительные-требования-для-драиверов"><a href="#предварительные-требования-для-драиверов" class="header-anchor">#</a> Предварительные требования для драйверов</h2><p>В большинстве случаев вы можете использовать драйвер SMTP, который поддерживается большинством почтовых провайдеров. Однако использование драйверов на основе API зачастую является более простым и быстрым подходом.</p><h3 id="драивер-mailgun"><a href="#драивер-mailgun" class="header-anchor">#</a> Драйвер Mailgun</h3><p>Для использования драйвера Mailgun установите транспорт Symfony Mailgun Mailer через Composer.</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">composer</span> require symfony/mailgun-mailer symfony/http-client
</code></pre></div><p>Затем установите параметр <code>driver</code> в файле конфигурации <code>config/mail.php</code> в значение <code>mailgun</code>. После этого убедитесь, что ваш файл конфигурации <code>config/services.php</code> содержит следующие параметры:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;mailgun&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;domain&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-mailgun-domain&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;secret&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-mailgun-key&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;endpoint&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;api.mailgun.net&#39;</span><span class="token punctuation">,</span> <span class="token comment">// api.eu.mailgun.net for EU</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h3 id="драивер-postmark"><a href="#драивер-postmark" class="header-anchor">#</a> Драйвер Postmark</h3><p>Для использования драйвера Postmark установите транспорт Symfony Postmark Mailer через Composer.</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">composer</span> require symfony/postmark-mailer symfony/http-client
</code></pre></div><p>Затем установите параметр <code>default</code> в файле конфигурации <code>config/mail.php</code> вашего приложения в значение postmark. После настройки почтового сервиса по умолчанию убедитесь, что ваш файл конфигурации <code>config/services.php</code> содержит следующее.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;postmark&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;token&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;POSTMARK_TOKEN&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h3 id="драивер-ses"><a href="#драивер-ses" class="header-anchor">#</a> Драйвер SES</h3><p>Для использования драйвера Amazon SES необходимо сначала установить Amazon AWS SDK для PHP. Вы можете установить эту библиотеку через менеджер пакетов Composer.</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">composer</span> require aws/aws-sdk-php
</code></pre></div><p>Затем установите параметр <code>driver</code> в файле конфигурации <code>config/mail.php</code> в значение <code>ses</code>. После этого убедитесь, что ваш файл конфигурации <code>config/services.php</code> содержит следующие параметры:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;ses&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-ses-key&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;secret&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-ses-secret&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;region&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;ses-region&#39;</span><span class="token punctuation">,</span>  <span class="token comment">// e.g. us-east-1</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h2 id="почта-и-локальная-разработка"><a href="#почта-и-локальная-разработка" class="header-anchor">#</a> Почта и локальная разработка</h2><p>При разработке приложения, отправляющего электронную почту, вы, вероятно, не захотите отправлять письма на реальные адреса электронной почты. Существует несколько способов «отключить» фактическую отправку сообщений.</p><h3 id="драивер-log"><a href="#драивер-log" class="header-anchor">#</a> Драйвер Log</h3><p>Одно из решений — использовать почтовый драйвер <code>log</code> во время локальной разработки. Этот драйвер записывает все сообщения электронной почты в файлы журнала для последующего просмотра. Для получения дополнительной информации о настройке приложения для различных окружений ознакомьтесь с <a href="./../setup/configuration.html">документацией по конфигурации</a>.</p><h3 id="универсальныи-получатель"><a href="#универсальныи-получатель" class="header-anchor">#</a> Универсальный получатель</h3><p>Другое решение — задать универсального получателя для всех писем, отправляемых фреймворком. Таким образом, все письма, генерируемые вашим приложением, будут отправляться на указанный адрес, а не на адрес, фактически заданный при отправке сообщения. Это можно сделать с помощью параметра <code>to</code> в файле конфигурации <code>config/mail.php</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;to&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;address&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dev@example.tld&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Dev Example&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h3 id="режим-имитации-отправки"><a href="#режим-имитации-отправки" class="header-anchor">#</a> Режим имитации отправки</h3><p>Вы можете динамически отключить отправку почты с помощью метода <code>Mail::pretend</code>. Когда почтовый сервис находится в режиме имитации, сообщения записываются в файлы журнала приложения вместо отправки получателю.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">pretend</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4>`,31)),n[2]||(n[2]=s("div",{class:"custom-block also"},[s("ul",null,[s("li",null,[s("a",{href:"./../extend/system/sending-mail.html"},"Отправка почты")]),s("li",null,[s("a",{href:"https://github.com/rainlab/sparkpost-plugin",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Плагин SparkPost"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])])])])],-1))])}const q=l(g,[["render",u]]);export{x as __pageData,q as default};
